    h, w = len(grid), len(grid[0])
    if h == 2 and w == 2:
        return [[grid[0][0], grid[0][1]], [grid[1][0], grid[0][0]]]
    # Reconstruct the diagonal stripe motif from the seed diagonals. The
    # smallest period that keeps differently colored seed stripes distinct
    # is used, and any unseeded phases repeat the closest observed color.
    seeds = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                seeds.setdefault(c - r, value)
    period = 1
    while True:
        phases = {}
        valid = True
        for d, value in seeds.items():
            phase = d % period
            if phase in phases and phases[phase] != value:
                valid = False
                break
            phases[phase] = value
        if valid and len(phases) == len(set(phases)):
            break
        period += 1
    # Fill unknown phases by cycling through known stripe colors in phase order.
    known = sorted(phases.items())
    motif = [None] * period
    for phase, color in known:
        motif[phase] = color
    for phase in range(period):
        if motif[phase] is None:
            prev = max((p for p in range(period) if motif[p] is not None), default=None)
            if prev is not None:
                motif[phase] = motif[prev]
            else:
                motif[phase] = 0
    return [[motif[(c-r) % period] for c in range(w)] for r in range(h)]
